-- 테셋 거시·국제 레슨 카드·퀴즈 (lesson_macro_2.sql): 실업률(802), 자연실업률(477), 소비자물가지수(CPI)(310), 스태그플레이션(334), 필립스곡선(642), 피셔효과(638), 총요소생산성(TFP)(764), 경기종합지수(25), 비교우위(266), 보호무역주의(244), 국제수지(BOP)(84), 구매력평가 환율(59), 선물환거래(296)
-- 근거: 테셋37~68 블로그 글. 각 단어 뒤에 text/table/flow 카드와 quiz 2개(그중 lessonCheck 1개)를 붙인다.
-- 첫 카드 제목이 이미 있으면 건너뜀(다시 실행해도 중복 없음). lessonCheck가 이미 있는 단어도 건너뜀.

-- 실업률 (802)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "실업률과 고용률은 분모가 달라요", "body": "실업률 = 실업자 ÷ 경제활동인구 × 100, 고용률 = 취업자 ÷ 15세 이상 생산가능인구 × 100이에요.\n실업자는 일하지 않았고, 지난 4주간 적극적으로 일자리를 찾았고, 바로 일할 수 있는 사람이에요.\n주 1시간 이상 돈을 받고 일했다면 아르바이트라도 취업자예요."},
  {"type": "table", "title": "인구는 이렇게 나눠요", "columns": ["구분", "누구"], "rows": [["생산가능인구", "15세 이상(군인·수감자 등 제외)"], ["경제활동인구", "취업자 + 실업자"], ["비경제활동인구", "학생·전업주부·구직 포기자처럼 일하지도 구직하지도 않는 사람"]]},
  {"type": "text", "title": "구직 포기의 함정", "body": "일자리를 못 찾아 구직을 포기한 사람은 실업자가 아니라 비경제활동인구가 돼요.\n그러면 실업자가 줄어 실업률은 내려가지만 취업자는 그대로라 고용률은 변하지 않아요. 그래서 실업률은 고용률과 함께 봐야 해요."},
  {"type": "quiz", "lessonCheck": true, "q": "실업자 일부가 구직을 포기해 비경제활동인구가 됐어요. 실업률과 고용률은 어떻게 될까요?", "options": ["실업률 그대로, 고용률↑", "둘 다 그대로", "실업률↓, 고용률 그대로", "실업률↑, 고용률↓"], "answer": 2, "explanation": "실업자가 경제활동인구에서 빠져 실업률은 내려가요. 하지만 취업자와 생산가능인구는 그대로라 고용률은 변하지 않아요."},
  {"type": "quiz", "q": "경제활동인구 200명 중 취업자가 190명, 실업자가 10명이에요. 실업률은?", "options": ["5%", "95%", "10%", "약 5.3%"], "answer": 0, "explanation": "실업률은 실업자 ÷ 경제활동인구 × 100이에요. 10 ÷ 200 × 100 = 5%예요."}]'::jsonb
WHERE id = 802 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "실업률과 고용률은 분모가 달라요"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 자연실업률 (477)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "table", "title": "실업의 세 종류와 대책", "columns": ["종류", "원인", "대책"], "rows": [["마찰적 실업", "이직·첫 구직 등 일자리를 찾는 과정", "일자리 정보망·직업 알선"], ["구조적 실업", "기술 발달·산업 구조 변화", "직업 재교육·훈련"], ["경기적 실업", "경기 침체로 일자리가 줄어듦", "재정·통화정책으로 총수요↑"]]},
  {"type": "text", "title": "완전고용이어도 실업률은 0%가 아니에요", "body": "경기적 실업이 없는 완전고용 상태에서도 마찰적·구조적 실업은 남아요. 이때의 실업률이 자연실업률이에요.\n자연실업률일 때의 생산량이 잠재GDP예요.\n총수요 정책으로는 경기적 실업만 줄일 수 있고, 자연실업률을 낮추려면 정보망·재교육 같은 대책이 필요해요."},
  {"type": "quiz", "lessonCheck": true, "q": "경기가 완전고용 수준인데도 실업률이 3%예요. 이 3%를 이루는 실업으로 알맞은 것은?", "options": ["실업이 아니라 통계 오류", "경기적 실업", "경기적 실업과 구조적 실업", "마찰적 실업과 구조적 실업"], "answer": 3, "explanation": "완전고용은 경기적 실업이 없는 상태예요. 그래도 남는 마찰적·구조적 실업의 비율이 자연실업률이에요."},
  {"type": "quiz", "q": "자연실업률을 낮추는 데 가장 알맞은 정책은?", "options": ["정부지출 확대", "구인·구직 정보망 확충과 직업 재교육", "통화량 증가", "기준금리 인하"], "answer": 1, "explanation": "자연실업률은 마찰적·구조적 실업이라 총수요를 늘려서는 줄지 않아요. 일자리 정보를 잘 연결하고 새 산업에 맞게 재교육해야 해요."}]'::jsonb
WHERE id = 477 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "실업의 세 종류와 대책"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 소비자물가지수(CPI) (310)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "장바구니 물가를 재는 지수", "body": "소비자물가지수는 가계가 주로 사는 상품과 서비스 수백 개의 가격 변화를 기준연도 = 100으로 나타낸 지수예요. 통계청이 작성해요.\n수입품도 포함하고, 집값은 빼고 전월세는 넣어요.\n한국은행 물가안정목표(2%)의 기준이 되는 지표예요."},
  {"type": "table", "title": "물가지수 세 가지", "columns": ["지표", "작성", "대상", "수입품"], "rows": [["소비자물가지수(CPI)", "통계청", "가계가 사는 상품·서비스", "포함"], ["생산자물가지수(PPI)", "한국은행", "국내 생산자가 출하하는 상품·서비스", "제외"], ["GDP 디플레이터", "한국은행", "국내에서 생산한 모든 최종 생산물", "제외"]], "caption": "CPI는 기준연도 수량을 고정해 계산해서(라스파이레스 방식) 물가 상승을 실제보다 크게 보여 주는 경향이 있어요."},
  {"type": "quiz", "lessonCheck": true, "q": "외국에서 수입해 그대로 파는 가전제품 값이 올랐어요. 이 가격 변화가 반영되는 물가지표는?", "options": ["소비자물가지수(CPI)", "GDP 디플레이터", "생산자물가지수(PPI)", "실질 GDP"], "answer": 0, "explanation": "CPI는 가계가 사는 물건이면 수입품도 포함해요. GDP 디플레이터와 PPI는 국내 생산이 기준이라 수입품을 빼요."},
  {"type": "quiz", "q": "소비자물가지수 계산에 들어가지 않는 것은?", "options": ["수입 식료품", "전세·월세", "주택 매매 가격(집값)", "외식비"], "answer": 2, "explanation": "집은 소비가 아니라 자산 구입으로 보아 집값은 CPI에서 빠져요. 대신 주거 서비스 비용인 전월세는 들어가요."}]'::jsonb
WHERE id = 310 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "장바구니 물가를 재는 지수"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 스태그플레이션 (334)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "불황인데 물가가 올라요", "body": "경기 침체(stagnation)와 인플레이션(inflation)이 함께 나타나는 현상이에요.\n원자재값·임금 같은 생산비가 오르면 단기 총공급(AS) 곡선이 왼쪽으로 가서 물가는 오르고 생산은 줄어요. 오일쇼크가 대표적인 예예요."},
  {"type": "table", "title": "수요 견인 vs 비용 인상", "columns": ["비교", "수요 견인 인플레이션", "비용 인상 인플레이션"], "rows": [["곡선", "AD 오른쪽", "단기 AS 왼쪽"], ["물가", "올라요", "올라요"], ["생산·소득", "늘어요", "줄어요"], ["대표 원인", "정부지출·통화량 증가", "원자재값·임금 급등"]]},
  {"type": "text", "title": "정책 딜레마", "body": "경기를 살리려 돈을 풀면 물가가 더 오르고, 물가를 잡으려 긴축하면 생산이 더 줄어요.\n그래서 기술 혁신·생산성 향상으로 총공급을 늘리는 공급 쪽 대책이 함께 필요해요."},
  {"type": "quiz", "lessonCheck": true, "q": "국제 유가가 급등해 기업들의 생산비가 크게 올랐어요. 단기적으로 나타날 가능성이 큰 것은?", "options": ["물가↓, 생산↑", "물가↓, 생산↓", "물가↑, 생산↑", "물가↑, 생산↓"], "answer": 3, "explanation": "생산비가 오르면 단기 총공급 곡선이 왼쪽으로 이동해 물가는 오르고 생산은 줄어요. 이게 스태그플레이션이에요."},
  {"type": "quiz", "q": "스태그플레이션 상황에서 확장적 통화정책을 쓰면 어떻게 될까요?", "options": ["물가와 실업이 함께 빠르게 안정된다", "생산은 늘 수 있지만 물가가 더 오른다", "아무 변화도 없다", "물가는 내리지만 생산이 더 줄어든다"], "answer": 1, "explanation": "총수요를 늘리면 생산은 회복될 수 있지만 이미 오르던 물가가 더 올라요. 물가와 경기를 동시에 잡기 어려운 이유예요."}]'::jsonb
WHERE id = 334 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "불황인데 물가가 올라요"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 필립스곡선 (642)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "실업률과 물가상승률의 상충관계", "body": "단기에는 실업률이 낮을수록 물가상승률이 높고, 실업률이 높을수록 물가상승률이 낮은 관계가 나타나요.\n총수요가 늘면 생산이 늘어 실업은 줄지만 물가는 오르기 때문이에요.\n그래서 물가 안정과 완전고용을 동시에 이루기 어려워요."},
  {"type": "table", "title": "단기와 장기", "columns": ["구분", "모양", "뜻"], "rows": [["단기 필립스곡선", "우하향", "물가 상승을 감수하면 실업을 줄일 수 있어요"], ["장기 필립스곡선", "자연실업률에서 수직", "기대 물가가 조정되면 실업률은 자연실업률로 돌아가요"]], "caption": "원자재값이 오르는 공급 충격이 오면 실업과 물가가 함께 올라 단기 곡선이 위로 이동해요."},
  {"type": "quiz", "lessonCheck": true, "q": "정부가 총수요를 늘려 단기적으로 실업률을 낮췄어요. 단기 필립스곡선에 따르면 함께 나타나기 쉬운 것은?", "options": ["자연실업률 하락", "물가상승률 상승", "물가상승률 하락", "잠재GDP 감소"], "answer": 1, "explanation": "단기 필립스곡선은 우하향이라 실업률이 내려가면 물가상승률이 올라가요. 실업과 물가 사이의 상충관계예요."},
  {"type": "quiz", "q": "장기 필립스곡선의 모양은?", "options": ["우하향", "자연실업률 수준에서 수직", "우상향", "수평"], "answer": 1, "explanation": "장기에는 사람들의 기대 물가가 실제 물가에 맞춰 조정돼요. 그래서 실업률은 자연실업률로 돌아가고 곡선은 수직이 돼요."}]'::jsonb
WHERE id = 642 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "실업률과 물가상승률의 상충관계"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 피셔효과 (638)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "명목이자율 = 실질이자율 + 예상 인플레이션", "body": "실질이자율 5%를 받고 싶은데 물가가 3% 오를 것 같으면 명목이자율은 8%여야 해요.\n그래서 사람들이 예상하는 물가상승률이 오르면 명목이자율도 거의 그만큼 따라 오르는데, 이를 피셔효과라고 해요.\n은행에 붙은 금리는 명목이자율이에요."},
  {"type": "table", "title": "예상 못한 인플레이션이면", "columns": ["불리한 쪽", "유리한 쪽"], "rows": [["채권자(돈 빌려준 사람)", "채무자(돈 빌린 사람)"], ["현금·예금 보유자", "실물자산 보유자"], ["봉급·연금 생활자", "정부(큰 채무자)"]], "caption": "미리 예상한 인플레이션은 이자율에 반영돼 피해가 작지만, 예상하지 못하면 부가 재분배돼요."},
  {"type": "quiz", "lessonCheck": true, "q": "실질이자율은 2%로 그대로인데 사람들이 예상하는 물가상승률이 1%에서 4%로 올랐어요. 피셔효과에 따르면 명목이자율은?", "options": ["3%에서 6%로 오른다", "4%로 정해진다", "2%로 그대로다", "1%로 내린다"], "answer": 0, "explanation": "명목이자율 = 실질이자율 + 예상 인플레이션이에요. 2 + 1 = 3%에서 2 + 4 = 6%로 올라요."},
  {"type": "quiz", "q": "명목이자율이 6%, 예상 물가상승률이 4%라면 실질이자율은?", "options": ["-2%", "2%", "10%", "1.5%"], "answer": 1, "explanation": "실질이자율 = 명목이자율 - 예상 인플레이션이에요. 6 - 4 = 2%예요."}]'::jsonb
WHERE id = 638 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "명목이자율 = 실질이자율 + 예상 인플레이션"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 총요소생산성(TFP) (764)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "투입을 늘리지 않고 느는 생산", "body": "생산은 자본(K), 노동(L), 그리고 기술·교육·제도 같은 생산 효율(A)로 정해져요. 이 A가 총요소생산성이에요.\n자본과 노동은 늘릴수록 추가 효과가 줄지만, 총요소생산성은 한계 없이 장기 성장을 이끌 수 있어요."},
  {"type": "table", "title": "성장회계로 쪼개 보기", "columns": ["성장률 5%를 쪼개면", "기여"], "rows": [["노동 투입 증가", "1%p"], ["자본 투입 증가", "2%p"], ["나머지(솔로 잔차 = 총요소생산성)", "2%p"]], "caption": "노동과 자본으로 설명하고 남은 부분을 총요소생산성의 기여로 봐요."},
  {"type": "quiz", "lessonCheck": true, "q": "경제성장률이 4%이고, 노동 투입 증가가 1%p, 자본 투입 증가가 2%p를 설명해요. 성장회계로 본 총요소생산성의 기여는?", "options": ["4%p", "1%p", "7%p", "3%p"], "answer": 1, "explanation": "노동과 자본으로 설명되지 않는 나머지가 총요소생산성의 기여예요. 4 - 1 - 2 = 1%p예요."},
  {"type": "quiz", "q": "총요소생산성을 높이는 요인으로 볼 수 없는 것은?", "options": ["제도 개선", "기술 혁신", "경영 효율 개선", "설비는 그대로 두고 근로자만 더 많이 고용하는 것"], "answer": 3, "explanation": "근로자를 더 고용하는 건 노동 투입을 늘리는 거예요. 총요소생산성은 투입이 같아도 더 많이 만들게 하는 기술·효율·제도의 몫이에요."}]'::jsonb
WHERE id = 764 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "투입을 늘리지 않고 느는 생산"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 경기종합지수 (25)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "여러 지표를 하나로 묶은 경기 지수", "body": "생산·소비·고용·금융 등 경기를 잘 보여 주는 여러 지표를 모아 하나로 합친 지수예요. 통계청이 작성해요.\n경기보다 먼저 움직이는 선행종합지수, 함께 움직이는 동행종합지수, 뒤따라 움직이는 후행종합지수로 나눠요."},
  {"type": "table", "title": "선행·동행·후행", "columns": ["구분", "움직임", "쓰임"], "rows": [["선행종합지수", "경기보다 먼저 움직여요", "앞으로의 경기 예측"], ["동행종합지수", "경기와 함께 움직여요", "지금 경기 판단"], ["후행종합지수", "경기가 바뀐 뒤 움직여요", "경기 흐름 확인"]]},
  {"type": "text", "title": "왜 미리 알아야 할까", "body": "지금이 호황인지 불황인지 알아야 재정·통화정책을 제때 쓸 수 있어요. 정책시차를 줄이려면 선행지표가 특히 중요해요.\n설문으로 만드는 심리지수(BSI·CSI)는 100, PMI는 50이 기준이라는 점과 구분해요."},
  {"type": "quiz", "lessonCheck": true, "q": "몇 달 뒤의 경기 흐름을 미리 가늠하려고 할 때 가장 알맞은 지표는?", "options": ["동행종합지수", "후행종합지수", "선행종합지수", "GDP 디플레이터"], "answer": 2, "explanation": "선행종합지수는 경기보다 먼저 움직이는 지표들로 만들어 앞으로의 경기를 예측하는 데 써요. 동행은 지금, 후행은 지나간 흐름을 보여 줘요."},
  {"type": "quiz", "q": "경기종합지수에 대한 설명으로 옳은 것은?", "options": ["한 가지 지표만으로 만든다", "여러 경제지표를 합쳐 선행·동행·후행으로 나눈다", "물가 수준을 재는 지수다", "기업가 설문으로 만들며 100이 기준이다"], "answer": 1, "explanation": "경기종합지수는 여러 지표를 합쳐 만들고 움직이는 시점에 따라 선행·동행·후행으로 나눠요. 설문으로 만드는 BSI와는 달라요."}]'::jsonb
WHERE id = 25 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "여러 지표를 하나로 묶은 경기 지수"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 비교우위 (266)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "table", "title": "절대우위 vs 비교우위", "columns": ["구분", "절대우위", "비교우위"], "rows": [["기준", "절대적인 생산비", "기회비용(상대적인 생산비)"], ["학자", "애덤 스미스", "리카도"], ["한 나라가 둘 다 잘할 때", "무역 이익을 설명 못 해요", "그래도 무역 이익이 있어요"]]},
  {"type": "table", "title": "기회비용으로 따져 보기", "columns": ["나라", "쌀 1단위 노동", "자동차 1대 노동", "쌀 1단위의 기회비용"], "rows": [["A국", "8명", "4명", "자동차 2대"], ["B국", "10명", "25명", "자동차 0.4대"]], "caption": "A국은 둘 다 절대우위지만, 쌀의 기회비용이 더 작은 B국이 쌀에, A국은 자동차에 비교우위가 있어요."},
  {"type": "text", "title": "교환 비율은 두 기회비용 사이", "body": "쌀 1단위를 자동차 0.4대에서 2대 사이로 바꾸면 두 나라 모두 이익이에요.\n두 재화 모두 절대열위인 나라도 비교우위는 반드시 하나씩 있어요."},
  {"type": "quiz", "lessonCheck": true, "q": "옷 1벌을 만들 때 A국은 신발 2켤레, B국은 신발 0.5켤레를 포기해야 해요. 비교우위에 따른 특화로 알맞은 것은?", "options": ["A국 신발, B국 옷", "두 나라 모두 무역 이익이 없다", "A국 옷, B국 신발", "두 나라 모두 옷"], "answer": 0, "explanation": "옷의 기회비용이 작은 B국이 옷에 비교우위가 있어요. A국은 신발 1켤레의 기회비용이 옷 0.5벌로 B국(옷 2벌)보다 작아 신발에 특화해요."},
  {"type": "quiz", "q": "비교우위를 판단하는 기준은?", "options": ["나라의 크기", "절대적인 생산비", "기회비용", "임금 수준의 높고 낮음"], "answer": 2, "explanation": "비교우위는 한 재화를 만들 때 포기하는 다른 재화의 양, 곧 기회비용이 더 작은 쪽에 있어요."}]'::jsonb
WHERE id = 266 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "절대우위 vs 비교우위"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 보호무역주의 (244)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "table", "title": "보호무역의 근거", "columns": ["근거", "내용"], "rows": [["유치산업 보호", "아직 어린 산업이 클 때까지 보호해요(프리드리히 리스트)"], ["안보", "식량·국방 산업은 자국에 있어야 해요"], ["공업 육성", "농업국에서 공업국으로 가려면 보호가 필요하다고 봐요"]]},
  {"type": "table", "title": "보호무역주의 vs 신보호무역주의", "columns": ["구분", "누가", "무엇을", "수단"], "rows": [["보호무역주의", "주로 개발도상국", "새로 크는 산업", "관세 중심"], ["신보호무역주의", "주로 선진국", "경쟁력을 잃는 사양산업", "비관세장벽 중심"]]},
  {"type": "text", "title": "경제학의 기본 입장", "body": "경제학은 대체로 자유무역이 비교우위에 따른 특화로 사회 전체 후생을 늘린다고 봐요.\n보호무역의 원래 논리는 \"어릴 때 잠깐\"이에요. 경쟁력을 잃은 산업을 오래 붙잡으면 효율이 떨어져요."},
  {"type": "quiz", "lessonCheck": true, "q": "한 개발도상국이 아직 경쟁력이 약한 자동차 산업을 키우려고 일정 기간 수입 자동차에 높은 관세를 매겼어요. 이 정책의 근거는?", "options": ["비교우위론", "유치산업 보호론", "구매력평가설", "신보호무역주의"], "answer": 1, "explanation": "어린 산업이 경쟁력을 갖출 때까지 잠깐 보호하자는 것이 유치산업 보호론이에요. 신보호무역주의는 선진국이 사양산업을 지키는 것이라 달라요."},
  {"type": "quiz", "q": "신보호무역주의의 특징으로 옳은 것은?", "options": ["개발도상국이 새 산업을 키우려고 관세를 쓴다", "선진국이 사양산업을 보호하려고 주로 비관세장벽을 쓴다", "모든 나라가 관세를 없앤다", "FTA로 회원국끼리 관세를 철폐한다"], "answer": 1, "explanation": "신보호무역주의는 선진국이 경쟁력을 잃어 가는 산업을 지키려고 수입 할당·각종 규제 같은 비관세장벽을 주로 쓰는 흐름이에요."}]'::jsonb
WHERE id = 244 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "보호무역의 근거"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 국제수지(BOP) (84)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "국적이 아니라 거주지, 합계는 늘 0", "body": "국제수지는 일정 기간 거주자와 비거주자 사이의 모든 경제적 거래를 기록해요. 우리나라에 사는 외국인도 우리나라 거주자예요.\n한 거래를 두 곳에 같은 크기로 적는 복식부기라 표 전체 합은 늘 0이에요. 그래서 뉴스의 흑자는 대부분 경상수지 흑자를 뜻해요."},
  {"type": "table", "title": "국제수지표의 구성", "columns": ["계정", "세부 항목", "예"], "rows": [["경상수지", "상품수지", "자동차·반도체 수출입"], ["경상수지", "서비스수지", "운송·여행·지식재산권 사용료"], ["경상수지", "본원소득수지", "임금·배당·이자"], ["경상수지", "이전소득수지", "대가 없는 송금·원조"], ["자본수지", "자본이전 등", "채무 면제, 특허권 자체 매매"], ["금융계정", "직접·증권·파생·기타투자, 준비자산", "해외 공장 설립, 주식·채권 매매, 외환보유액 증감"]], "caption": "거래 자체는 금융계정, 그 대가로 받는 배당·이자는 경상수지에 적어요."},
  {"type": "quiz", "lessonCheck": true, "q": "한국 투자자가 미국 회사 주식을 사고, 1년 뒤 그 주식에서 배당을 받았어요. 각각 국제수지의 어디에 기록될까요?", "options": ["주식 매입은 서비스수지, 배당은 이전소득수지", "둘 다 자본수지", "둘 다 상품수지", "주식 매입은 금융계정, 배당은 본원소득수지"], "answer": 3, "explanation": "주식 같은 금융자산을 사고파는 건 금융계정이에요. 그 투자로 받은 배당·이자는 경상수지 안의 본원소득수지에 들어가요."},
  {"type": "quiz", "q": "국제수지에서 거주자를 나누는 기준은?", "options": ["외화 보유 여부", "사는 곳(거주지)", "나이", "국적"], "answer": 1, "explanation": "국제수지는 국적이 아니라 그 나라에 사는지로 거주자를 나눠요. 우리나라에 사는 외국인도 거주자예요."}]'::jsonb
WHERE id = 84 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "국적이 아니라 거주지, 합계는 늘 0"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 구매력평가 환율 (59)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "같은 물건은 어디서나 같은 값", "body": "구매력평가설은 같은 물건은 어느 나라에서든 같은 값이어야 한다는 일물일가에서 출발해요.\n사과 1개가 한국에서 2,000원, 미국에서 5달러라면 구매력평가 환율은 1달러 = 400원이에요.\n물가는 천천히 움직여서 장기 환율을 설명하는 이론으로 써요."},
  {"type": "table", "title": "절대적 PPP vs 상대적 PPP", "columns": ["종류", "내용", "예"], "rows": [["절대적 구매력평가", "물건값 자체를 비교", "사과 2,000원 = 5달러 → 1달러 = 400원"], ["상대적 구매력평가", "두 나라 물가 상승률 차이만큼 환율이 변해요", "한국 물가 5%, 미국 3% 상승 → 원/달러 환율 약 2% 상승"]]},
  {"type": "text", "title": "현실과 다른 이유", "body": "관세와 운송비가 있고, 이발처럼 나라 사이에 거래되지 않는 서비스가 많아요. 품질 차이도 있어서 실제 환율은 구매력평가 환율과 차이가 날 수 있어요.\n단기 환율은 이자율 차이에 따른 자본 이동(이자율평형설)으로 설명해요."},
  {"type": "quiz", "lessonCheck": true, "q": "상대적 구매력평가설에 따르면, 한국 물가가 6%, 미국 물가가 2% 오를 때 원/달러 환율은?", "options": ["약 4% 오른다(원화 약세)", "변하지 않는다", "약 4% 내린다(원화 강세)", "약 8% 오른다"], "answer": 0, "explanation": "물가가 더 많이 오르는 나라의 통화 가치가 그 차이만큼 떨어져요. 6 - 2 = 4%만큼 원/달러 환율이 올라요."},
  {"type": "quiz", "q": "햄버거가 한국에서 6,000원, 미국에서 4달러예요. 절대적 구매력평가에 따른 환율은?", "options": ["1달러 = 1,000원", "1달러 = 1,500원", "1달러 = 24,000원", "1달러 = 2,400원"], "answer": 1, "explanation": "같은 햄버거의 값이 같아지는 환율을 구하면 돼요. 6,000원 ÷ 4달러 = 1달러당 1,500원이에요."}]'::jsonb
WHERE id = 59 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "같은 물건은 어디서나 같은 값"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 선물환거래 (296)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "미래 환율을 지금 정해 두는 계약", "body": "수출입 기업은 계약할 때와 대금을 받을 때 사이에 환율이 변하는 위험(환위험)을 져요.\n선물환거래는 미래 특정 시점에 주고받을 환율을 지금 미리 정해 두는 계약이에요. 이렇게 환위험을 줄이는 걸 환헤지라고 해요."},
  {"type": "table", "title": "100만 달러 수출 대금, 6개월 뒤", "columns": ["6개월 뒤 환율", "헤지 안 함", "선물환 1,000원에 매도 계약"], "rows": [["500원", "5억 원", "10억 원"], ["1,000원", "10억 원", "10억 원"], ["2,000원", "20억 원", "10억 원"]], "caption": "큰 손실도 큰 이익도 포기하고 받을 금액을 미리 확정하는 거예요."},
  {"type": "quiz", "lessonCheck": true, "q": "3개월 뒤 수출 대금 100만 달러를 받는 기업이 그사이 환율 하락이 걱정돼요. 선물환으로 할 수 있는 조치는?", "options": ["원화 예금을 늘린다", "3개월 뒤 달러를 정해진 환율에 파는 선물환 계약을 맺는다", "대금을 받는 날 시장 환율로만 바꾼다", "3개월 뒤 달러를 정해진 환율에 사는 선물환 계약을 맺는다"], "answer": 1, "explanation": "받을 달러를 미리 정한 환율에 파는 선물환 매도 계약을 맺으면, 환율이 내려도 원화로 받을 금액이 확정돼요."},
  {"type": "quiz", "q": "수출 기업이 선물환 매도 계약으로 환율을 1,000원에 고정했는데 실제 환율이 1,200원으로 올랐어요. 결과로 옳은 것은?", "options": ["1,200원 기준으로 받는다", "계약이 자동으로 취소된다", "1,100원으로 평균해서 받는다", "1,000원 기준으로 받아 환율 상승의 추가 이익은 얻지 못한다"], "answer": 3, "explanation": "선물환은 환율이 어떻게 변하든 미리 정한 환율로 거래해요. 손실을 피하는 대신 환율이 유리하게 움직여도 그 이익은 포기해요."}]'::jsonb
WHERE id = 296 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "미래 환율을 지금 정해 두는 계약"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

NOTIFY pgrst, 'reload schema';

